raw_rows = props.get("links") or []
if isinstance(raw_rows, str):
	try:
		raw_rows = json.loads(raw_rows)
	except Exception:
		raw_rows = [line for line in raw_rows.split("\n") if line.strip()]
if not isinstance(raw_rows, list):
	raw_rows = []
rows = []
for raw in raw_rows:
	try:
		parts = [part.strip() for part in str(raw).split("|")]
		while len(parts) < 2:
			parts.append("")
		if parts[0] or parts[1]:
			rows.append(parts)
	except Exception:
		continue

links = []
for parts in rows:
	links.append({"label": parts[0], "href": parts[1] or "#"})
component.links = links
